fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // For three points on a line, the sum of distances to a meeting point
    // is minimized when the meeting point is the median of the three.
    let mut xs = [x1, x2, x3];
    xs.sort_unstable();
    let median = xs[1];
    (x1 - median).abs() + (x2 - median).abs() + (x3 - median).abs()
}

